def maximumStrongPairXor(nums):
    max_xor = 0
    n = len(nums)
    # Try all pairs (i, j) including i == j
    for i in range(n):
        for j in range(n):
            x, y = nums[i], nums[j]
            if abs(x - y) <= min(x, y):
                candidate = x ^ y
                if candidate > max_xor:
                    max_xor = candidate
    return max_xor
